  select array_agg(x) into criteria from jsonb_array_elements_text(v->'criteria') x;
  select coalesce(array_agg(x),'{}') into deps from jsonb_array_elements_text(v->'deps') x;
  select * into previous from public.growth_development_tasks where task_key=v->>'task_key';
  if found then
   -- Only untouched backlog is reconciled. Concurrent human progress must be reviewed.
   if previous.initiative_id is distinct from project.id or previous.status<>'backlog' or cardinality(previous.completed_criteria)>0 or previous.resolution is not null then raise exception 'insurance_task_changed: %',v->>'task_key';end if;
   update public.growth_development_tasks set title=v->>'title',acceptance_criteria=criteria,dependencies=deps,
    details=details||jsonb_build_object('insurance_group',v->>'group','wiki_pilot_note','05-Estrategia/Estrategia-de-Segmentacao-de-Seguros.md','previous_title',previous.title,'previous_acceptance_criteria',to_jsonb(previous.acceptance_criteria)::text,'previous_dependencies',to_jsonb(previous.dependencies)::text,'revision_reason','Compatibilização autorizada do plano em 09/11/2026'),
    next_action=criteria[1],revision=revision+1,updated_at=clock_timestamp() where id=previous.id;
  else
   insert into public.growth_development_tasks(task_key,title,description,area,priority,status,owner_label,dependencies,acceptance_criteria,completed_criteria,resolution,source_note,created_by,revision,workspace,work_type,initiative_id,details,links,next_action)
   values(v->>'task_key',v->>'title',coalesce(v->>'description',''),'Seguros','P1',case when v->>'done' is not null then 'concluida' else 'backlog' end,v->>'owner',deps,criteria,case when v->>'done' is not null then array[0] else '{}'::integer[] end,v->>'evidence','05-Estrategia/Estrategia-de-Segmentacao-de-Seguros.md',project.created_by,1,project.workspace,'task',project.id,
    jsonb_build_object('insurance_group',v->>'group','wiki_pilot_note','05-Estrategia/Estrategia-de-Segmentacao-de-Seguros.md','provenance','Plano editorial autorizado por Pablo em 09/11/2026; cadastro técnico via migração')||case when v->>'done' is not null then jsonb_build_object('completed_on',v->>'done') else '{}'::jsonb end,
    jsonb_build_array(jsonb_build_object('label','Estratégia e critérios de Seguros','url','05-Estrategia/Estrategia-de-Segmentacao-de-Seguros.md','kind','note','state','confirmed')),coalesce(criteria[1],''));
  end if;
 end loop;
end $seed$;
